"""
stage3_notion_sync.py - Stage 3: Notion 同步

将论文同步到Notion数据库，自动创建schema。
CleanRL设计: 单文件完整实现，可独立运行

输入: data/stage1_hf_papers/*.jsonl, data/stage2_ar5iv/*.json
输出: Notion pages + data/stage3_notion/sync_state.json
"""

import asyncio
from datetime import datetime
from typing import List, Optional, Dict, Any

from notion_client import AsyncClient
from loguru import logger

from config import settings, PAPER_CATEGORIES
from models import (
    HFPaper,
    Ar5ivContent,
    NotionSyncState,
    FullPaper,
    StageStats,
)
from utils import (
    setup_logging,
    save_json,
    load_json,
    truncate_text,
    format_exception,
    ProgressTracker,
)
from stage1_hf_scraper import load_stage1_results
from stage2_ar5iv_scraper import load_stage2_results


# ==================== Rich Text 辅助函数 ====================

def rich_text(
    content: str,
    bold: bool = False,
    italic: bool = False,
    color: str = None,
    link: str = None,
) -> Dict[str, Any]:
    """
    创建Notion rich_text对象

    注意: annotations必须与text同级，不能放在text内部
    """
    text_obj = {"content": content}
    if link:
        text_obj["link"] = {"url": link}

    result = {"type": "text", "text": text_obj}

    annotations = {}
    if bold:
        annotations["bold"] = True
    if italic:
        annotations["italic"] = True
    if color:
        annotations["color"] = color

    if annotations:
        result["annotations"] = annotations

    return result


def simple_text(content: str) -> Dict[str, Any]:
    """简单文本"""
    return {"type": "text", "text": {"content": content}}


# ==================== Notion Client ====================

class NotionSync:
    """
    Notion 同步器

    Stage 3: 同步到Notion数据库
    """

    # 推荐的数据库属性
    REQUIRED_PROPERTIES = {
        "Paper ID": {"rich_text": {}},
        "Authors": {"rich_text": {}},
        "Category": {"select": {"options": [
            {"name": cat["en"], "color": "blue"} 
            for cat in PAPER_CATEGORIES.values()
        ]}},
        "Keywords": {"multi_select": {"options": []}},
        "Labels": {"multi_select": {"options": []}},
        "Upvotes": {"number": {"format": "number"}},
        "Organization": {"rich_text": {}},
        "Month": {"rich_text": {}},
        "arXiv URL": {"url": {}},
        "HuggingFace URL": {"url": {}},
        "Abstract": {"rich_text": {}},
    }

    def __init__(
        self,
        token: str = None,
        database_id: str = None,
    ):
        self.token = token or settings.notion_token
        self.database_id = database_id or settings.notion_database_id

        if not self.token:
            raise ValueError("请设置 NOTION_TOKEN")
        if not self.database_id:
            raise ValueError("请设置 NOTION_DATABASE_ID")

        self.client = AsyncClient(auth=self.token)

        # 数据库schema
        self._db_schema: Dict[str, str] = {}
        self._title_property: str = "Name"

        # 同步状态
        self._sync_states: Dict[str, NotionSyncState] = {}

        # 统计
        self.stats = StageStats(stage="stage3_notion")

    async def connect(self) -> bool:
        """连接并初始化数据库schema"""
        try:
            db_info = await self.client.databases.retrieve(database_id=self.database_id)

            # 解析现有属性
            self._db_schema = {}
            for name, info in db_info.get("properties", {}).items():
                prop_type = info.get("type")
                self._db_schema[name] = prop_type
                if prop_type == "title":
                    self._title_property = name

            logger.info(f"✅ Notion连接成功")
            logger.info(f"   标题属性: {self._title_property}")
            logger.info(f"   现有属性: {list(self._db_schema.keys())}")

            # 自动创建缺失属性
            await self._create_missing_properties()

            # 加载同步状态
            await self._load_sync_state()

            return True

        except Exception:
            logger.error(f"❌ Notion连接失败: {format_exception()}")
            return False

    async def _create_missing_properties(self):
        """自动创建缺失的属性"""
        missing = {
            name: config
            for name, config in self.REQUIRED_PROPERTIES.items()
            if name not in self._db_schema
        }

        if not missing:
            logger.info("✅ 数据库schema完整")
            return

        logger.info(f"🔧 创建 {len(missing)} 个缺失属性...")

        try:
            await self.client.databases.update(
                database_id=self.database_id,
                properties=missing,
            )

            # 重新获取schema
            db_info = await self.client.databases.retrieve(database_id=self.database_id)
            self._db_schema = {}
            for name, info in db_info.get("properties", {}).items():
                self._db_schema[name] = info.get("type")

            logger.info(f"✅ 成功创建属性: {list(missing.keys())}")

        except Exception:
            logger.warning(f"⚠️ 自动创建属性失败: {format_exception()}")
            logger.warning("请确保Integration有编辑数据库权限")

    def _has_property(self, name: str) -> bool:
        """检查属性是否存在"""
        return name in self._db_schema

    async def _load_sync_state(self):
        """加载同步状态"""
        filepath = settings.get_notion_state_file()
        data = await load_json(filepath)
        if data:
            for paper_id, state_data in data.items():
                self._sync_states[paper_id] = NotionSyncState(**state_data)
            logger.info(f"📂 加载同步状态: {len(self._sync_states)} 条记录")

    async def _save_sync_state(self):
        """保存同步状态"""
        filepath = settings.get_notion_state_file()
        data = {
            paper_id: state.model_dump()
            for paper_id, state in self._sync_states.items()
        }
        await save_json(data, filepath)

    def _build_properties(
        self,
        paper: HFPaper,
        content: Ar5ivContent = None,
    ) -> Dict[str, Any]:
        """构建数据库属性"""
        props = {}

        # 标题（必须）
        props[self._title_property] = {
            "title": [simple_text(truncate_text(paper.title, 100))]
        }

        # Paper ID
        if self._has_property("Paper ID"):
            props["Paper ID"] = {
                "rich_text": [simple_text(paper.paper_id)]
            }

        # Authors
        if self._has_property("Authors") and content and content.authors:
            props["Authors"] = {
                "rich_text": [simple_text(", ".join(content.authors[:5]))]
            }

        # Upvotes
        if self._has_property("Upvotes"):
            props["Upvotes"] = {"number": paper.metrics.upvotes}

        # Organization
        if self._has_property("Organization") and paper.organization:
            props["Organization"] = {
                "rich_text": [simple_text(paper.organization.name)]
            }

        # Month
        if self._has_property("Month"):
            props["Month"] = {
                "rich_text": [simple_text(paper.month)]
            }

        # URLs
        if self._has_property("arXiv URL"):
            props["arXiv URL"] = {"url": paper.arxiv_url}
        if self._has_property("HuggingFace URL"):
            props["HuggingFace URL"] = {"url": paper.url}

        # Abstract
        if self._has_property("Abstract") and content and content.abstract:
            props["Abstract"] = {
                "rich_text": [simple_text(truncate_text(content.abstract, 2000))]
            }

        return props

    def _build_page_content(
        self,
        paper: HFPaper,
        content: Ar5ivContent = None,
    ) -> List[Dict[str, Any]]:
        """构建页面内容块"""
        blocks = []

        # 标题横幅
        blocks.append({
            "object": "block",
            "type": "callout",
            "callout": {
                "rich_text": [simple_text(f"📚 {paper.title}")],
                "icon": {"emoji": "📄"},
                "color": "blue_background",
            }
        })

        # 元信息
        blocks.append({
            "object": "block",
            "type": "heading_2",
            "heading_2": {"rich_text": [simple_text("📋 论文信息")]}
        })

        # 作者
        if content and content.authors:
            blocks.append({
                "object": "block",
                "type": "paragraph",
                "paragraph": {
                    "rich_text": [
                        rich_text("👥 作者: ", bold=True),
                        simple_text(", ".join(content.authors[:10])),
                    ]
                }
            })

        # 统计
        blocks.append({
            "object": "block",
            "type": "paragraph",
            "paragraph": {
                "rich_text": [
                    rich_text("📊 统计: ", bold=True),
                    simple_text(f"👍 {paper.metrics.upvotes} votes"),
                    simple_text(f" | 💬 {paper.metrics.comments} comments"),
                ]
            }
        })

        # 链接
        blocks.append({
            "object": "block",
            "type": "paragraph",
            "paragraph": {
                "rich_text": [
                    rich_text("🔗 链接: ", bold=True),
                    rich_text("arXiv", link=paper.arxiv_url),
                    simple_text(" | "),
                    rich_text("PDF", link=f"https://arxiv.org/pdf/{paper.paper_id}.pdf"),
                    simple_text(" | "),
                    rich_text("ar5iv", link=paper.ar5iv_url),
                    simple_text(" | "),
                    rich_text("HuggingFace", link=paper.url),
                ]
            }
        })

        blocks.append({"object": "block", "type": "divider", "divider": {}})

        # 摘要
        if content and content.abstract:
            blocks.append({
                "object": "block",
                "type": "heading_2",
                "heading_2": {"rich_text": [simple_text("📝 摘要")]}
            })

            # 分段
            abstract = content.abstract
            for i in range(0, len(abstract), 2000):
                blocks.append({
                    "object": "block",
                    "type": "paragraph",
                    "paragraph": {"rich_text": [simple_text(abstract[i:i+2000])]}
                })

        # 论文结构（如果有内容）
        if content and content.sections:
            blocks.append({"object": "block", "type": "divider", "divider": {}})
            blocks.append({
                "object": "block",
                "type": "heading_2",
                "heading_2": {"rich_text": [simple_text("📚 论文结构")]}
            })

            for section in content.sections[:10]:
                blocks.append({
                    "object": "block",
                    "type": "toggle",
                    "toggle": {
                        "rich_text": [simple_text(f"📖 {section.title}")],
                        "children": [
                            {
                                "object": "block",
                                "type": "paragraph",
                                "paragraph": {"rich_text": [simple_text(truncate_text(para, 500))]}
                            }
                            for para in section.paragraphs[:3]
                        ] if section.paragraphs else []
                    }
                })

        # 页脚
        blocks.append({"object": "block", "type": "divider", "divider": {}})
        blocks.append({
            "object": "block",
            "type": "paragraph",
            "paragraph": {
                "rich_text": [
                    rich_text(
                        f"同步时间: {datetime.now():%Y-%m-%d %H:%M:%S}",
                        italic=True,
                        color="gray",
                    )
                ]
            }
        })

        return blocks[:100]  # Notion限制

    async def find_existing_page(self, paper_id: str) -> Optional[str]:
        """查找已存在的页面"""
        # 先检查缓存
        if paper_id in self._sync_states:
            state = self._sync_states[paper_id]
            if state.status == "synced" and state.notion_page_id:
                return state.notion_page_id

        # 查询数据库
        try:
            if self._has_property("Paper ID"):
                response = await self.client.databases.query(
                    database_id=self.database_id,
                    filter={
                        "property": "Paper ID",
                        "rich_text": {"equals": paper_id}
                    }
                )
                if response["results"]:
                    return response["results"][0]["id"]
        except Exception:
            pass

        return None

    async def sync_paper(
        self,
        paper: HFPaper,
        content: Ar5ivContent = None,
        update_existing: bool = False,
    ) -> Optional[str]:
        """
        同步单篇论文到Notion

        Returns:
            页面ID或None
        """
        try:
            # 检查是否已存在
            existing_id = await self.find_existing_page(paper.paper_id)

            if existing_id and not update_existing:
                logger.debug(f"⏭️ 跳过已存在: {paper.paper_id}")
                self.stats.skipped += 1
                return existing_id

            # 构建属性和内容
            properties = self._build_properties(paper, content)
            blocks = self._build_page_content(paper, content)

            if existing_id:
                # 更新
                await self.client.pages.update(
                    page_id=existing_id,
                    properties=properties,
                )
                page_id = existing_id
                logger.info(f"🔄 更新: {paper.paper_id}")
            else:
                # 创建
                response = await self.client.pages.create(
                    parent={"database_id": self.database_id},
                    properties=properties,
                    children=blocks,
                )
                page_id = response["id"]
                logger.info(f"✅ 创建: {paper.paper_id}")

            # 更新状态
            self._sync_states[paper.paper_id] = NotionSyncState(
                paper_id=paper.paper_id,
                notion_page_id=page_id,
                synced_at=datetime.now(),
                status="synced",
            )
            self.stats.success += 1

            return page_id

        except Exception:
            error = format_exception()
            logger.error(f"❌ 同步失败 {paper.paper_id}: {error}")

            self._sync_states[paper.paper_id] = NotionSyncState(
                paper_id=paper.paper_id,
                status="failed",
                error=str(error),
            )
            self.stats.failed += 1

            return None

    async def run(
        self,
        papers: List[HFPaper] = None,
        contents: Dict[str, Ar5ivContent] = None,
        update_existing: bool = False,
        delay: float = 0.5,
    ) -> Dict[str, Any]:
        """
        运行Stage 3同步

        Args:
            papers: 论文列表
            contents: 内容字典 {paper_id: Ar5ivContent}
            update_existing: 是否更新已存在的
            delay: 请求间隔
        """
        # 加载论文
        if papers is None:
            papers = await load_stage1_results()

        if not papers:
            logger.warning("⚠️ 没有论文需要同步")
            return {}

        # 加载内容
        if contents is None:
            content_list = await load_stage2_results()
            contents = {c.paper_id: c for c in content_list}

        logger.info(f"🚀 Stage 3: 同步 {len(papers)} 篇论文到Notion")

        self.stats.total = len(papers)
        progress = ProgressTracker(len(papers), "Stage 3")

        # 逐个同步（Notion API有速率限制）
        for paper in papers:
            content = contents.get(paper.paper_id)
            await self.sync_paper(paper, content, update_existing)
            await asyncio.sleep(delay)
            progress.update()

        progress.finish()
        self.stats.end_time = datetime.now()

        # 保存状态
        await self._save_sync_state()

        logger.info(f"📊 Stage 3 完成:")
        logger.info(f"   总计: {self.stats.total}")
        logger.info(f"   成功: {self.stats.success}")
        logger.info(f"   跳过: {self.stats.skipped}")
        logger.info(f"   失败: {self.stats.failed}")
        logger.info(f"   耗时: {self.stats.duration_seconds:.1f}s")

        return {
            "synced": self.stats.success,
            "skipped": self.stats.skipped,
            "failed": self.stats.failed,
        }


async def main():
    """Stage 3 入口"""
    import argparse

    parser = argparse.ArgumentParser(description="Stage 3: Notion 同步")
    parser.add_argument("--update", action="store_true", help="更新已存在的页面")
    parser.add_argument("--limit", type=int, help="限制处理数量")
    parser.add_argument("--test", action="store_true", help="测试模式（只处理3篇）")
    args = parser.parse_args()

    # 设置日志
    settings.ensure_directories()
    setup_logging(settings.logs_dir)

    logger.info("=" * 60)
    logger.info("Stage 3: Notion 同步")
    logger.info("=" * 60)

    # 检查配置
    if not settings.notion_token:
        logger.error("❌ 请设置 NOTION_TOKEN 环境变量")
        return
    if not settings.notion_database_id:
        logger.error("❌ 请设置 NOTION_DATABASE_ID 环境变量")
        return

    try:
        sync = NotionSync()

        # 连接
        if not await sync.connect():
            return

        # 加载数据
        papers = await load_stage1_results()

        if not papers:
            logger.error("❌ 请先运行 Stage 1")
            return

        # 限制数量
        if args.test:
            papers = papers[:3]
            logger.info("🧪 测试模式: 只处理3篇")
        elif args.limit:
            papers = papers[:args.limit]

        # 运行同步
        await sync.run(papers=papers, update_existing=args.update)

    except Exception:
        logger.error(f"❌ 错误: {format_exception()}")


if __name__ == "__main__":
    asyncio.run(main())
